facilityFormItem.valueChangedEventHandler:
        var initiatorId = formItem.value || functions.getValues().Initiator;
        if (initiatorId != null) {
          functions.setDataSource('VacationKind', `/api/functions/GetAvailibleVacationKindsAndDays?employeeId=${initiatorId}`);
          if (functions.getValues().VacationKind !== null){
            functions.setValue('Duration', null);
          }

          ESS.network.sendRequest(`/api/functions/GetAvailibleVacationKindsAndDays?employeeId=${initiatorId}`) 
          .then(function (vacationKindsDaysData) {
            var availableKindsAndDays = JSON.stringify(vacationKindsDaysData);
            functions.setValue('AvailableKindsAndDays', availableKindsAndDays);
          })
          .catch(function (error) {
            ESS.toasts.showToast(error.message, ESS.enums.ToastType.ERROR, false);
          });
        
          context.checkEmployeeConsentSigned({ functions, context, employeeId: initiatorId });
        
          ESS.network.sendRequest(`/api/functions/GetEmployeeDepartmentManager?employeeId=${initiatorId}`)
          .then(function (manager){
            functions.setValue('Substitute', manager);
          })
        }

var initiatorId = functions.getValues().Initiator;
ESS.network.sendRequest(`/api/functions/GetAvailibleVacationKindsAndDays?employeeId=${initiatorId}`)
.then(function (vacationKindsDaysData) {
  var availableKindsAndDays = JSON.parse(JSON.stringify(vacationKindsDaysData));
  var alignDateAssignmentId = functions.getValues()['AlignDateAssignmentId'];
  if (availableKindsAndDays) {
    if (!alignDateAssignmentId) {
      availableKindsAndDays.forEach(function (vacationData) {
        if (vacationData.Id == formItem.value) {
          functions.setValue('BeginDate', new Date());
          functions.setValue('Duration', vacationData.Count);
          functions.setValue('Field_Вид_отпуска', vacationData.Name.toLowerCase());
        }
      });
    }
    else {
      ESS.network.sendRequest(`/api/functions/FillVacationDataForAlign?assignmentId=${alignDateAssignmentId}`)
      .then(function (vacationData){
        functions.setValue('BeginDate', vacationData.Begin);
        functions.setValue('Duration', vacationData.Duration);
        availableKindsAndDays.forEach(function (vacationData) {
          if (vacationData.Id == formItem.value) {
            functions.setValue('Field_Вид_отпуска', vacationData.Name.toLowerCase());
          }
        });
      });
    }
  }
})
.catch(function (error) {
  ESS.toasts.showToast(error.message, ESS.enums.ToastType.ERROR, false);
});

facilityFormItem.onClickEventHandler:
        const id = 'getVacationPlanningTool';
        const callDialog = () => {
          if (!Object.keys(context.canShowDialog).length) {
            const timeline = {
              type: ESS.enums.DialogItemType.TEXT,
              name: 'timeline',
              properties: {
                text: `
                  <component
                    name="VacationPlanningTool"
                    public-name="Directum_VacationPlanningTool_1_0"
                    module-name="loaders"
                    loader-name="lk-loader"
                    dialog-id="${id}"
                  />
                `,
              },
            };

            const performerId = {
              type: ESS.enums.DialogItemType.INPUT,
              name: 'PerformerId',
              properties: {
                initialValue: functions.getValues().Initiator,
                isHidden: true,
              },
            };

            const vacationKind = {
              type: ESS.enums.DialogItemType.INPUT,
              name: 'VacationKind',
              properties: {
                initialValue: functions.getValues().VacationKind,
                isHidden: true,
              },
            };

            const beginDate = {
              type: ESS.enums.DialogItemType.INPUT,
              name: 'BeginDate',
              properties: {
                initialValue: functions.getValues().BeginDate,
                isHidden: true,
              },
            };

            const duration = {
              type: ESS.enums.DialogItemType.INPUT,
              name: 'Duration',
              properties: {
                initialValue: functions.getValues().Duration,
                isHidden: true,
              },
            };

            const endDate = {
              type: ESS.enums.DialogItemType.INPUT,
              name: 'EndDate',
              properties: {
                initialValue: functions.getValues().EndDate,
                isHidden: true,
              },
            };

            const entityGuid = {
              type: ESS.enums.DialogItemType.INPUT,
              name: 'EntityGuid',
              properties: {
                initialValue: 'd1899307-092b-4a08-87b5-3c7c14f2feff',
                isHidden: true,
              },
            };

            const items = [
              timeline,
              performerId,
              vacationKind,
              beginDate,
              duration,
              endDate,
              entityGuid
            ];

            ESS.dialogs.createDialog({
              id,
              properties: {
                width: ESS.enums.DialogWidth.WIDE,
                isFullScreen: true,
              },
              title: ESS.L('@HRPROVACATIONS.FACILITIES_SCHEDULEVACATION_DIALOG_TITLE'),
              items,
            });
            clearInterval(intervalId);
          }
        }

        let intervalId = setInterval(callDialog, 300);

facilityFormItem.valueChangedEventHandler:
        var employeeId = formItem.value;
        var initiatorId = functions.getValues().Initiator;

        functions.removeError(window.errorSubstitute);
        if (employeeId == initiatorId){
          window.errorSubstitute = functions.showError(ESS.L('@HRPROVACATIONS.FACILITIES_GETVACATION_ERROR_SUBSTITUTE'));
        }

        if (employeeId) {
            functions.setValue('SubstituteId', employeeId);
        }
        else {
          functions.setValue('SubstituteId', 0);
        }

