facility.openingEventHandler:
    context.canShowDialog = {};
    context.sendRequest = (...args) => {
      const key = Date.now();
      context.canShowDialog[key] = '';
      return ESS.network.sendRequest(...args).finally(() => delete context.canShowDialog[key]);
    };
    var initiatorId = functions.getValues().Initiator;
    context.checkEmployeeConsentSigned = ESS.scripts.HRProVacations.checkEmployeeConsentSigned;
    context.checkEmployeeConsentSigned({ functions, context, employeeId: initiatorId });
    if (initiatorId != null){
      ESS.network.sendRequest(`/api/functions/GetEmployeeDepartmentManager?employeeId=${initiatorId}`)
      .then(function (manager){
        functions.setValue('Substitute', manager);
      });    
    }
    else {
      ESS.network.sendRequest(`/api/functions/GetEmployeeDepartmentManager?employeeId=$(CurrentUser.DirectumRX.ActorId)`)
      .then(function (manager){
        functions.setValue('Substitute', manager);
      });    
    }

    ESS.network.sendRequest(`/api/functions/GetEmployeeCertificates`)
    .then(function (certs) {
      if (certs.length == 0) {
          ESS.dialogs.showMessageBox(ESS.L('@HRPROVACATIONS.ERROR_COMMON'), ESS.L('@HRPROVACATIONS.FACILITIES_SENDSTATEMENT_NO_CERTIFICATES_ERROR'));
          reject();
      } else {
        ESS.network.sendRequest(`/api/functions/GetPostListByPerson`)
          .then(function (employee){
              ESS.network.sendRequest(`/api/functions/CheckEmployeeConsentSigned`)
                .then(function (isConsentSigned) {
                  if (isConsentSigned != true && employee.positions.length == 1) {
                    ESS.dialogs.showMessageBox(ESS.L('@HRPROVACATIONS.ERROR_COMMON'), ESS.L('@HRPROVACATIONS.FACILITIES_GETVACATION_CONSENT_ERROR'));
                    reject();                    
                  }
                  else
                  {
                    ESS.network.sendRequest(`/api/functions/GetVacationStatementTemplateId?employeeId=${initiatorId}&isShiftVacation=false`)
                    .then(function (VacationStatementData) {
                      if (VacationStatementData.Error.length == 0) {
                        var templateId = JSON.parse(VacationStatementData.TemplateId);
                        var docKindId = JSON.parse(VacationStatementData.DocumentKindId);
                        functions.setValue('TemplateId', templateId);
                        functions.setValue('DocumentKindId', docKindId);
                        functions.setValue('IsFromEssAccount', true);
                        resolve();
                        var alignDateAssignmentId = functions.getValues()['AlignDateAssignmentId'];
                        if (alignDateAssignmentId)
                        {
                          functions.setValue('TemplateId', templateId);
                          functions.setValue('DocumentKindId', docKindId);
                          ESS.network.sendRequest(`/api/functions/FillVacationDataForAlign?assignmentId=${alignDateAssignmentId}`)
                            .then(function (vacationData){
                              functions.setValue('VacationKind', vacationData.VacationKindId);
                            });
                          var substitute = functions.getValues().Substitute;
                          if (substitute == null){
                            ESS.network.sendRequest(`/api/functions/GetEmployeeDepartmentManager?employeeId=${initiatorId}`)
                              .then(function (manager){
                                functions.setValue('Substitute', manager);
                              });
                            }
                            resolve();
                          }
                          resolve();
                        } else {
                          ESS.dialogs.showMessageBox(ESS.L('@HRPROVACATIONS.ERROR_COMMON'), VacationStatementData.Error);
                      }
                    })
                  .catch(function (error) {
                      ESS.toasts.showToast(error.message, ESS.enums.ToastType.ERROR, false);
                  })
                }
              });             
          })
      }
    })
    .catch(function (error) {
      ESS.toasts.showToast(error.message, ESS.enums.ToastType.ERROR, false);
    });

facility.openedEventHandler:
    window.isEmpty = function (value)
    {
      return (value == null || value.length === 0);
    }

    window.getErrors = function (avaliableDays = null)
    {
      var values = functions.getValues();

      var initiator = values.Initiator;
      var vacationKind = values.VacationKind;
      var beginDate = values.BeginDate;
      var duration = values.Duration;

      if (!window.isEmpty(vacationKind) && !window.isEmpty(beginDate) && !window.isEmpty(duration))
      {
        var url = `/api/functions/ValidateVacationData?vacationKindId=${vacationKind}&startDate=${beginDate}&duration=${duration}&employeeId=${initiator}`
        var checkVacationErrors = ESS.network.sendRequest(url)
          .then(function (errors){
            functions.removeError(window.errorVacations);
            if(errors.length > 0){
              window.errorVacations = functions.showError(errors);
            }
        })
        .catch(function (error){
          ESS.toasts.showToast(error.message, ESS.enums.ToastType.ERROR, false);
          reject();
        });
        Promise.allSettled([
          checkVacationErrors
        ]).then(results => {});
      }

      functions.removeError(window.errorDate);
      var today = new Date();
      var yesterday = new Date(today);
      yesterday.setDate(today.getDate() -1);
      var dateFromControl = new Date(beginDate).getTime();
       
      if (dateFromControl < yesterday.getTime())
      {
        window.errorDate = functions.showError(ESS.L('@HRPROVACATIONS.ERROR_DATE_BEGIN'));
      }
    }

facility.beforeValidationEventHandler:

  const intervalId = setInterval(() => {
    if (!functions.isItemDisabled('Duration') && !functions.isItemDisabled('BeginDate')) {
      clearInterval(intervalId);
      resolve();
    }
  }, 300);

facility.closedEventHandler:
if (sender.performingAction === 'SUBMIT_FACILITY_PARAMETERS') 
{
  ESS.closeElement(sender.parent); 
  ESS.widgets.updateWidgets();
}
delete window.isEmpty;
delete window.getErrors;
